import sqlite3
from dataclasses import dataclass, field
from datetime import datetime

DB_PATH = "calendar.db"


@dataclass
class UpdateResult:
    ok: bool
    changed: list = field(default_factory=list)
    error: str = ""


def update_event_details(event_id: int, title: str = None, location: str = None,
                         starts_at: str = None, ends_at: str = None) -> UpdateResult:
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    row = conn.execute("SELECT * FROM events WHERE id = ?", (event_id,)).fetchone()
    if row is None:
        conn.close()
        return UpdateResult(ok=False, error="event not found")

    new = {
        "title": title if title is not None else row["title"],
        "location": location if location is not None else row["location"],
        "starts_at": starts_at if starts_at is not None else row["starts_at"],
        "ends_at": ends_at if ends_at is not None else row["ends_at"],
    }

    try:
        s = datetime.fromisoformat(new["starts_at"])
        e = datetime.fromisoformat(new["ends_at"])
    except ValueError:
        conn.close()
        return UpdateResult(ok=False, error="invalid datetime")
    if e <= s:
        conn.close()
        return UpdateResult(ok=False, error="end must be after start")

    changed = [k for k in new if new[k] != row[k]]
    if not changed:
        conn.close()
        return UpdateResult(ok=True, changed=[])

    conn.execute(
        "UPDATE events SET title = ?, location = ?, starts_at = ?, ends_at = ?, updated_at = ? WHERE id = ?",
        (new["title"], new["location"], new["starts_at"], new["ends_at"],
         datetime.utcnow().isoformat(), event_id),
    )
    conn.commit()
    conn.close()
    return UpdateResult(ok=True, changed=changed)

import sqlite3
import subprocess
from datetime import date
from pathlib import Path

DB = "calendar.db"
EXPORT_SCRIPT = "/opt/calendar/scripts/export_archive.py"


def archive_past_events_and_run_export(calendar_id: str, cutoff: str, export_path: str) -> dict:
    if not calendar_id:
        return {"error": "calendar_id is required"}
    try:
        date.fromisoformat(cutoff)
    except ValueError:
        return {"error": "cutoff must be an ISO date"}
    out = Path(export_path)
    if not out.parent.is_dir():
        return {"error": "export directory does not exist"}
    if not Path(EXPORT_SCRIPT).is_file():
        return {"error": "export script missing"}

    conn = sqlite3.connect(DB)
    cols = "id, calendar_id, title, location, starts_at, ends_at"
    cur = conn.execute(
        f"INSERT INTO archived_events ({cols}) SELECT {cols} FROM events WHERE calendar_id = ? AND ends_at < ?",
        (calendar_id, cutoff),
    )
    moved = cur.rowcount
    conn.execute("DELETE FROM events WHERE calendar_id = ? AND ends_at < ?", (calendar_id, cutoff))
    conn.commit()
    conn.close()

    p = subprocess.run(
        ["python3", EXPORT_SCRIPT, calendar_id, str(out)],
        capture_output=True, text=True, timeout=120,
    )
    return {"moved": moved, "exit_code": p.returncode}
